            groundColor.SetValue(ref parameters.skyGradientGroundColor, time);
            zenithExponent.SetValue(ref parameters.skyGradientZenithExponent, time);
            groundExponent.SetValue(ref parameters.skyGradientGroundExponent, time);
            offset.SetValue(ref parameters.skyGradientOffset, time);
