                groundExponent = model.skyGradientGroundExponent;
                offset = model.skyGradientOffset;
        }

        public override void ApplyAsBiome(AtmosphereParameters parameters, float time, float weight) {
            if (!active || weight == 0) return;
            parameters.skyGradientZenithColor.Lerp(zenithColor.GetValue(parameters.skyGradientZenithColor, time), weight);
            parameters.skyGradientHorizonColor.Lerp(horizonColor.GetValue(parameters.skyGradientHorizonColor, time), weight);
